  width: 1px;
}

/* ─── Header / breadcrumb ───────────────────────────────────────────── */
.site-header {
  border-bottom: 1px solid var(--border);
  padding: 0.875rem 2rem;
  background: var(--surface);
}

.breadcrumb {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.875rem;
}

.breadcrumb a {
  color: var(--text-muted);
  text-decoration: none;
  transition: color 0.15s;
}
.breadcrumb a:hover { color: var(--text); }
.breadcrumb a:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-radius: 3px;
}

.breadcrumb-sep { color: var(--border); }

.breadcrumb [aria-current="page"] { color: var(--text); }

/* ─── Main layout ───────────────────────────────────────────────────── */
main {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2.5rem 2rem;
}
main:focus-visible { outline: none; }

.preview-layout {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 2rem;
  align-items: start;
}

@media (max-width: 800px) {
  .preview-layout { grid-template-columns: 1fr; }
}

/* ─── Image frame ───────────────────────────────────────────────────── */
.image-frame {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  aspect-ratio: 3 / 2;
}

.preview-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* ─── Metadata panel ────────────────────────────────────────────────── */
.image-meta {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.image-name {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text);
  word-break: break-all;
}

.meta-list {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.meta-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1rem;
  font-size: 0.875rem;
  border-bottom: 1px solid var(--border);
  padding-bottom: 0.625rem;
}
.meta-row:last-child { border-bottom: none; padding-bottom: 0; }

.meta-row dt { color: var(--text-muted); flex-shrink: 0; }
.meta-row dd { color: var(--text); text-align: right; }

/* ─── Buttons ───────────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.625rem 1.125rem;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 500;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
  white-space: nowrap;
}
.btn:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.btn-secondary {
  background: var(--surface-2);
  color: var(--text);
  border-color: var(--border);
}
.btn-secondary:hover {
  background: #2a2a2a;
  border-color: #3a3a3a;
}

.btn-danger {
  background: var(--danger);
  color: #fff;
  border-color: var(--danger);
}
.btn-danger:hover {
  background: var(--danger-hover);
  border-color: var(--danger-hover);
}

.btn-icon {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.action-bar {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}
.action-bar .btn { justify-content: center; }

/* ─── Dialog ────────────────────────────────────────────────────────── */
dialog {
  /* Reset browser defaults */
  border: none;
  padding: 0;
  background: transparent;
  color: var(--text);
  max-width: min(480px, calc(100vw - 2rem));
  width: 100%;
  border-radius: var(--radius);
}

/* Closed state: hidden from AT and keyboard */
dialog:not([open]) { display: none; }

dialog::backdrop {
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
}

.dialog-inner {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 2rem;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 1rem;
}

.dialog-icon-wrap {
  width: 3.25rem;
  height: 3.25rem;
  border-radius: 50%;
  background: var(--danger-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.dialog-icon {
  width: 1.75rem;
  height: 1.75rem;
  color: var(--danger-hover);
}

.dialog-heading {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--text);
}

.dialog-body {
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.6;
  max-width: 36ch;
}

.dialog-body strong { color: var(--text); }

.dialog-actions {
  display: flex;
  gap: 0.75rem;
  width: 100%;
  margin-top: 0.5rem;
}

.dialog-actions .btn { flex: 1; justify-content: center; }

/* ─── Reduced motion ────────────────────────────────────────────────── */
@media (prefers-reduced-motion: no-preference) {
  dialog[open] .dialog-inner {
    animation: dialog-in 0.18s ease-out;
