  @keyframes dialog-in {
    from { opacity: 0; transform: scale(0.96) translateY(-8px); }
    to   { opacity: 1; transform: scale(1)    translateY(0); }
  }
}

/* ─── Forced colors ─────────────────────────────────────────────────── */
@media (forced-colors: active) {
  .btn-danger { border-color: ButtonText; }
  dialog::backdrop { background: Canvas; }
}
