*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:           #0d0d0d;
  --surface:      #181818;
  --surface-2:    #222222;
  --border:       #2e2e2e;
  --text:         #e8e8e8;
  --text-muted:   #8a8a8a;
  --accent:       #6366f1;
  --accent-hover: #818cf8;
  --danger:       #dc2626;
  --danger-hover: #ef4444;
  --danger-muted: rgba(220, 38, 38, 0.15);
  --radius:       10px;
  --radius-sm:    6px;
  --shadow-lg:    0 25px 60px rgba(0, 0, 0, 0.7);
  --focus-ring:   0 0 0 3px rgba(99, 102, 241, 0.6);
}

html { color-scheme: dark; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Helvetica, Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100dvh;
}

/* ─── Skip link ────────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: 1rem;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
}
.skip-link:not(:focus):not(:active) {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

/* ─── Header / breadcrumb ───────────────────────────────────────────── */
.site-header {
  border-bottom: 1px solid var(--border);
  padding: 0.875rem 2rem;
  background: var(--surface);
}

.breadcrumb {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.875rem;
}

.breadcrumb a {
  color: var(--text-muted);
  text-decoration: none;
  transition: color 0.15s;
}
.breadcrumb a:hover { color: var(--text); }
.breadcrumb a:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-radius: 3px;
}

.breadcrumb-sep { color: var(--border); }

.breadcrumb [aria-current="page"] { color: var(--text); }

/* ─── Main layout ───────────────────────────────────────────────────── */
main {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2.5rem 2rem;
}
main:focus-visible { outline: none; }

.preview-layout {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 2rem;
  align-items: start;
}

@media (max-width: 800px) {
  .preview-layout { grid-template-columns: 1fr; }
}

/* ─── Image frame ───────────────────────────────────────────────────── */
.image-frame {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  aspect-ratio: 3 / 2;
}

.preview-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* ─── Metadata panel ────────────────────────────────────────────────── */
.image-meta {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
