const { chromium } = require('/tmp/node_modules/playwright');
const fs = require('fs');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const html = fs.readFileSync('index.html', 'utf8');
  const css  = fs.readFileSync('styles.css', 'utf8');
  const js   = fs.readFileSync('script.js', 'utf8');
  const inlined = html
    .replace('<link rel=\"stylesheet\" href=\"styles.css\" />', '<style>' + css + '</style>')
    .replace('<script src=\"script.js\"></script>', '<script>' + js + '</script>');
  await page.setContent(inlined, { waitUntil: 'load' });
  await page.click('#delete-trigger');
  await page.waitForSelector('dialog[open]');
  // Check computed styles
  const styles = await page.evaluate(function() {
    var btn = document.getElementById('dialog-confirm');
    var cs = window.getComputedStyle(btn);
    var dlg = document.getElementById('delete-dialog');
    var dcs = window.getComputedStyle(dlg);
    return {
      btnColor: cs.color,
      btnBg: cs.backgroundColor,
      dialogBg: dcs.backgroundColor,
      dialogOpacity: dcs.opacity
    };
  });
  console.log('Computed styles:', JSON.stringify(styles, null, 2));
  await browser.close();
})().catch(function(e){ console.error('ERROR:', e.message); process.exit(2); });
