  const browser = await chromium.launch();
  const page = await browser.newPage();
  // Add dialog-inner div + btn classes to isolate
  const html = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><style>
  html { color-scheme: dark; }
  :root { --bg: #0d0d0d; --surface: #181818; --surface-2: #222222; --border: #2e2e2e; --text: #e8e8e8; --danger: #dc2626; --radius: 10px; --radius-sm: 6px; }
  body { background: var(--bg); color: var(--text); }
  dialog { background: var(--surface); color: var(--text); border: none; padding: 0; border-radius: var(--radius); overflow: hidden; max-width: 480px; width: 100%; }
  dialog::backdrop { background: rgba(0,0,0,0.75); }
  dialog:not([open]) { display: none; }
  .dialog-inner { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 2rem; display: flex; flex-direction: column; align-items: center; gap: 1rem; }
  .dialog-actions { display: flex; gap: 0.75rem; width: 100%; margin-top: 0.5rem; }
  .btn { display: inline-flex; align-items: center; gap: 0.5rem; padding: 0.625rem 1.125rem; border: 1px solid transparent; border-radius: var(--radius-sm); font-size: 0.9rem; font-weight: 500; cursor: pointer; white-space: nowrap; flex: 1; justify-content: center; }
  .btn-secondary { background: var(--surface-2); color: var(--text); border-color: var(--border); }
  .btn-danger { background: var(--danger); color: #fff; border-color: var(--danger); }
  </style></head><body>
  <button id="trigger">Open</button>
  <dialog id="dlg" aria-labelledby="h">
    <div class="dialog-inner">
      <h2 id="h">Delete?</h2>
      <div class="dialog-actions">
        <button class="btn btn-secondary" id="cancel">Cancel</button>
        <button class="btn btn-danger" id="ok">Delete image</button>
      </div>
    </div>
  </dialog>
  <script>
  document.getElementById('trigger').onclick = function(){ document.getElementById('dlg').showModal(); document.getElementById('cancel').focus(); };
  document.getElementById('cancel').onclick = function(){ document.getElementById('dlg').close(); };
  document.getElementById('ok').onclick = function(){ document.getElementById('dlg').close(); };
  </script></body></html>`;
  await page.setContent(html, { waitUntil: 'load' });
  await page.click('#trigger');
  await page.waitForSelector('dialog[open]');
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const raw = await page.evaluate('axe.run().then(function(r){ return JSON.stringify(r); })');
  await browser.close();
  const results = JSON.parse(raw);
  const cv = results.violations.find(function(v){ return v.id === 'color-contrast'; });
  if (cv) {
    cv.nodes.forEach(function(n) {
      console.log('FAIL:', n.html.substring(0, 80));
      console.log('Data:', JSON.stringify(n.any[0].data));
    });
  } else {
    console.log('PASS: no violations');
  }
})().catch(function(e){ console.error('ERROR:', e.message); process.exit(2); });
