   clip: rect(0 0 0 0);
   clip-path: inset(50%);
   height: 1px;
   overflow: hidden;
   position: absolute;
   white-space: nowrap;
   width: 1px;
 }

 /* ─── Header / breadcrumb ───────────────────────────────────────────── */
 .site-header {
   border-bottom: 1px solid var(--border);
   padding: 0.875rem 2rem;
