 }

 .btn-icon {
   width: 1rem;
   height: 1rem;
   flex-shrink: 0;
 }

 .action-bar {
   display: flex;
   flex-direction: column;
   gap: 0.625rem;
 }
 .action-bar .btn { justify-content: center; }

 /* ─── Dialog ────────────────────────────────────────────────────────── */
