/* ─── Reset & base ─────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:           #0d0d0d;
  --surface:      #181818;
  --surface-2:    #222222;
  --border:       #2e2e2e;
  --text:         #e8e8e8;
  --text-muted:   #8a8a8a;
  --accent:       #6366f1;
  --accent-hover: #818cf8;
  --danger:       #dc2626;
  --danger-hover: #ef4444;
  --danger-muted: rgba(220, 38, 38, 0.15);
  --radius:       10px;
  --radius-sm:    6px;
  --shadow-lg:    0 25px 60px rgba(0, 0, 0, 0.7);
  --focus-ring:   0 0 0 3px rgba(99, 102, 241, 0.6);
}

html { color-scheme: dark; }

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Helvetica, Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100dvh;
}

/* ─── Skip link ────────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: 1rem;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
}
.skip-link:not(:focus):not(:active) {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

/* ─── Header / breadcrumb ───────────────────────────────────────────── */
.site-header {
  border-bottom: 1px solid var(--border);
  padding: 0.875rem 2rem;
  background: var(--surface);
}

.breadcrumb {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.875rem;
}

.breadcrumb a {
  color: var(--text-muted);
  text-decoration: none;
  transition: color 0.15s;
}
.breadcrumb a:hover { color: var(--text); }
.breadcrumb a:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-radius: 3px;
}

.breadcrumb-sep { color: var(--border); }

.breadcrumb [aria-current="page"] { color: var(--text); }

/* ─── Main layout ───────────────────────────────────────────────────── */
main {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2.5rem 2rem;
}
main:focus-visible { outline: none; }

.preview-layout {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 2rem;
  align-items: start;
}

@media (max-width: 800px) {
  .preview-layout { grid-template-columns: 1fr; }
}

/* ─── Image frame ───────────────────────────────────────────────────── */
.image-frame {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  aspect-ratio: 3 / 2;
}

.preview-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* ─── Metadata panel ────────────────────────────────────────────────── */
.image-meta {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.image-name {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text);
  word-break: break-all;
}

.meta-list {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.meta-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1rem;
  font-size: 0.875rem;
  border-bottom: 1px solid var(--border);
  padding-bottom: 0.625rem;
}
.meta-row:last-child { border-bottom: none; padding-bottom: 0; }

.meta-row dt { color: var(--text-muted); flex-shrink: 0; }
.meta-row dd { color: var(--text); text-align: right; }

/* ─── Buttons ───────────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.625rem 1.125rem;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 500;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
  white-space: nowrap;
}
.btn:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.btn-secondary {
  background: var(--surface-2);
  color: var(--text);
  border-color: var(--border);
}
.btn-secondary:hover {
  background: #2a2a2a;
  border-color: #3a3a3a;
}

.btn-danger {
  background: var(--danger);
  color: #fff;
  border-color: var(--danger);
}
.btn-danger:hover {
  background: var(--danger-hover);
  border-color: var(--danger-hover);
}

.btn-icon {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.action-bar {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}
.action-bar .btn { justify-content: center; }

/* ─── Dialog ────────────────────────────────────────────────────────── */
dialog {
  /* Reset browser defaults */
  border: none;
  padding: 0;
  /* Solid background so the ::backdrop colour doesn't bleed into contrast
     calculations for child elements when axe traverses the stacking context. */
  background: var(--surface);
  color: var(--text);
  max-width: min(480px, calc(100vw - 2rem));
  width: 100%;
  border-radius: var(--radius);
  overflow: hidden;
}

/* Closed state: hidden from AT and keyboard */
dialog:not([open]) { display: none; }

dialog::backdrop {
  background: rgba(0, 0, 0, 0.75);
}

.dialog-inner {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 2rem;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 1rem;
}

.dialog-icon-wrap {
  width: 3.25rem;
  height: 3.25rem;
  border-radius: 50%;
  background: var(--danger-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.dialog-icon {
  width: 1.75rem;
  height: 1.75rem;
  color: var(--danger-hover);
}

.dialog-heading {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--text);
}

.dialog-body {
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.6;
  max-width: 36ch;
}

.dialog-body strong { color: var(--text); }

.dialog-actions {
  display: flex;
  gap: 0.75rem;
  width: 100%;
  margin-top: 0.5rem;
}

.dialog-actions .btn { flex: 1; justify-content: center; }

/* ─── Reduced motion ────────────────────────────────────────────────── */
@media (prefers-reduced-motion: no-preference) {
  dialog[open] .dialog-inner {
    animation: dialog-in 0.18s ease-out;
  }

  /* opacity intentionally omitted: opacity transitions on focusable content
