  @keyframes dialog-in {
    from { transform: scale(0.96) translateY(-8px); }
    to   { transform: scale(1)    translateY(0); }
  }
}

/* ─── Forced colors ─────────────────────────────────────────────────── */
@media (forced-colors: active) {
  .btn-danger { border-color: ButtonText; }
  dialog::backdrop { background: Canvas; }
}
