const { chromium } = require('/tmp/node_modules/playwright');
const fs = require('fs');

(async () => {
  const src = fs.readFileSync('index.html', 'utf8');
  const browser = await chromium.launch();
  var allWcag = [], allBp = [];

  // Pass 1: closed state
  var page = await browser.newPage();
  await page.setContent(src, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  var r1 = JSON.parse(await page.evaluate('axe.run().then(function(r){ return JSON.stringify(r); })'));
  await page.close();

  // Pass 2: open-dialog state (after animation)
  page = await browser.newPage();
  await page.setContent(src, { waitUntil: 'load' });
  await page.click('#delete-trigger');
  await page.waitForSelector('dialog[open]');
  await page.waitForTimeout(300);
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  var r2 = JSON.parse(await page.evaluate('axe.run().then(function(r){ return JSON.stringify(r); })'));
  await page.close();

  await browser.close();

  [r1, r2].forEach(function(r, i) {
    var label = i === 0 ? 'closed' : 'open';
    r.violations.forEach(function(v) {
      var isBp = v.tags.indexOf('best-practice') !== -1;
      var obj = { state: label, id: v.id, impact: v.impact };
      if (isBp) allBp.push(obj); else allWcag.push(obj);
    });
  });

  if (allWcag.length === 0 && allBp.length === 0) {
    console.log('PASS — 0 WCAG violations, 0 best-practice items (both states tested)');
  } else {
    console.log(JSON.stringify({ wcag: allWcag, bp: allBp }, null, 2));
  }
  process.exit(allWcag.length > 0 ? 1 : 0);
})().catch(function(e){ console.error('ERROR:', e.message); process.exit(2); });
